def semver_sort(versions):
    def parse(v):
        core = v
        build = None
        if '+' in core:
            core, build = core.split('+', 1)
        pre = None
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is not None:
            idents = pre.split('.')
        else:
            idents = None
        return (major, minor, patch, idents)

    def ident_key(ident):
        if ident.isdigit():
            return (0, int(ident))
        else:
            return (1, ident)

    def cmp_key(v):
        major, minor, patch, idents = parse(v)
        if idents is None:
            pre_flag = 1
            idents_key = ()
        else:
            pre_flag = 0
            idents_key = tuple(ident_key(i) for i in idents)
        return (major, minor, patch, pre_flag, idents_key, len(idents_key))

    import functools
    def compare(a, b):
        ka = cmp_key(a)
        kb = cmp_key(b)
        # compare major,minor,patch,pre_flag first
        if ka[:4] != kb[:4]:
            return -1 if ka[:4] < kb[:4] else 1
        # compare idents_key element by element
        ia, ib = ka[4], kb[4]
        for x, y in zip(ia, ib):
            if x != y:
                return -1 if x < y else 1
        if len(ia) != len(ib):
            return -1 if len(ia) < len(ib) else 1
        return 0

    return sorted(versions, key=functools.cmp_to_key(compare))

